program='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            box = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if box <= cells:
                pieces.append((1, box))
            for (dr, dc), color in (((0, 0), 2), ((0, 1), 4), ((1, 0), 3), ((1, 1), 5)):
                shape = box - {(r + dr, c + dc)}
                if shape <= cells:
                    pieces.append((color, shape))

    solutions = []
    def search(remaining, chosen):
        if not remaining:
            solutions.append(chosen)
            return
        cell = min(remaining)
        for color, shape in pieces:
            if cell in shape and shape <= remaining:
                search(remaining - shape, chosen + [(color, shape)])
    search(cells, [])
    result = [[0] * cols for _ in range(rows)]
    for color, shape in solutions[0]:
        for r, c in shape:
            result[r][c] = color
    return result
'''
